// src/mock/users.js

export const getUserData = async (username, password) => {
  try {
    const response = await fetch('http://localhost/your-api-endpoint.php', {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
      },
      body: JSON.stringify({
        usuario: username,
        contrasena: password
      })
    });

    const data = await response.json();

    if (data.success) {
      return {
        success: true,
        role: data.rol,
        ci: data.ci,
        name: data.name,
        initial: data.initial
      };
    } else {
      return {
        success: false,
        error: data.error
      };
    }
  } catch (error) {
    console.error('Error al obtener los datos del usuario:', error);
    return {
      success: false,
      error: 'Error de conexión con el servidor'
    };
  }
};
